$ErrorActionPreference='Stop'
$p='C:\Users\M\CLINE\tools\automation_server.py'
if(Test-Path -LiteralPath $p){{throw "Jau yra: $p"}}
[IO.File]::WriteAllBytes($p,[Convert]::FromBase64String(''))
$p='C:\Users\M\CLINE\tools\automation-server-loop.ps1'
if(Test-Path -LiteralPath $p){{throw "Jau yra: $p"}}
[IO.File]::WriteAllBytes($p,[Convert]::FromBase64String(''))
$p='C:\Users\M\CLINE\tools\cline-auto-workflow-v2-template.json'
if(Test-Path -LiteralPath $p){{throw "Jau yra: $p"}}
[IO.File]::WriteAllBytes($p,[Convert]::FromBase64String(''))
$secretFile='C:\Users\M\CLINE\tools\automation-secret.txt'
if(Test-Path $secretFile){{throw 'Secret jau yra'}}
$bytes=New-Object byte[] 32;(New-Object Security.Cryptography.RNGCryptoServiceProvider).GetBytes($bytes);$token=([BitConverter]::ToString($bytes)).Replace('-','').ToLower()
[IO.File]::WriteAllText($secretFile,$token,[Text.UTF8Encoding]::new($false))
$tpl=[IO.File]::ReadAllText('C:\Users\M\CLINE\tools\cline-auto-workflow-v2-template.json')
$final=$tpl.Replace('__AUTOMATION_KEY__',$token)
[IO.File]::WriteAllText('C:\Users\M\CLINE\tools\cline-auto-workflow-v2.json',$final,[Text.UTF8Encoding]::new($false))
$final|ConvertFrom-Json|Out-Null
$loop='C:\Users\M\CLINE\tools\automation-server-loop.ps1'
Start-Process -FilePath 'C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe' -ArgumentList @('-NoProfile','-WindowStyle','Hidden','-ExecutionPolicy','Bypass','-File',('"'+$loop+'"')) -WindowStyle Hidden
$ok=$false;for($i=0;$i -lt 20;$i++){{Start-Sleep -Milliseconds 500;try{{$h=Invoke-WebRequest 'http://127.0.0.1:8792/health' -UseBasicParsing -TimeoutSec 2;if($h.StatusCode -eq 200){{$ok=$true;break}}}}catch{{}}}}
Write-Output ('AUTOMATION_API_HEALTH='+$ok)
if(-not $ok){{throw 'Automation API nepaleistas'}}
foreach($action in @('ensure','collect')){{$r=Invoke-RestMethod -Uri ('http://127.0.0.1:8792/'+$action) -Method Post -Headers @{'X-Automation-Key'=$token} -TimeoutSec 130;Write-Output ($action+'_OK='+$r.ok+' EXIT='+$r.results[0].exit_code)}}
Get-Item -LiteralPath $secretFile,'C:\Users\M\CLINE\tools\automation_server.py','C:\Users\M\CLINE\tools\cline-auto-workflow-v2.json'|Select-Object Name,Length,LastWriteTime|Format-Table -AutoSize